      const expiresAt = new Date(now.getTime() + 60 * 60 * 1000);

      await prisma.passwordResetToken.deleteMany({
        where: { email },
      });

      await prisma.passwordResetToken.create({
        data: {
          token,
          email,
          expiresAt,
        },
      });
    }

