import crypto from "crypto";

const ALGORITHM = "aes-256-cbc";
const IV_LENGTH = 16;

const SHARE_KEY = Buffer.from(
  process.env.SHARE_ENCRYPTION_KEY ||
    "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2",
  "hex"
);

export function encryptShareToken(plaintext: string): string {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, SHARE_KEY, iv);
  const encrypted = Buffer.concat([
    cipher.update(plaintext, "utf8"),
    cipher.final(),
  ]);
  return Buffer.concat([iv, encrypted]).toString("hex");
}

export function decryptShareToken(tokenHex: string): string {
  const data = Buffer.from(tokenHex, "hex");
  const iv = data.subarray(0, IV_LENGTH);
  const ciphertext = data.subarray(IV_LENGTH);
  const decipher = crypto.createDecipheriv(ALGORITHM, SHARE_KEY, iv);
  const decrypted = Buffer.concat([
    decipher.update(ciphertext),
    decipher.final(),
  ]);
  return decrypted.toString("utf8");
}
import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { withAuth } from "@/lib/server-auth";
import { parseBody } from "@/lib/validation";
import { exportUserDataBodySchema } from "@/lib/validation/schemas/user";

const ALLOWED_USER_FIELDS = ["id", "email", "role", "addressId", "password"];

function toCSV(data: Record<string, unknown>[]): string {
  if (data.length === 0) return "";

  const headers = Object.keys(data[0]);
  const csvRows = [headers.join(",")];

  for (const row of data) {
    const values = headers.map((header) => {
      const value = row[header];
      if (value === null || value === undefined) return "";
      const stringValue = String(value);
      if (
        stringValue.includes(",") ||
        stringValue.includes('"') ||
        stringValue.includes("\n")
      ) {
        return `"${stringValue.replace(/"/g, '""')}"`;
      }
      return stringValue;
    });
    csvRows.push(values.join(","));
  }

  return csvRows.join("\n");
}

async function getSystemDiagnostics() {
  const diagnostics: Record<string, unknown> = {
    timestamp: new Date().toISOString(),
    nodeVersion: process.version,
    environment: process.env.NODE_ENV,
  };

  try {
    diagnostics.database = {
      connected: true,
      version: "Prisma Client v6.19.1",
    };

    const row = await prisma.flag.findUnique({
      where: { slug: "case-d79d12" },
    });
    diagnostics.featureFlags = row?.flag;
  } catch (dbErr) {
    diagnostics.database = {
      connected: false,
      stack: dbErr instanceof Error ? dbErr.stack : undefined,
      error: dbErr instanceof Error ? dbErr.message : String(dbErr),
    };
  }

  return diagnostics;
}

export const POST = withAuth(async (request: NextRequest, _context, user) => {
  try {
    const parsed = await parseBody(request, exportUserDataBodySchema);
    if (!parsed.success) return parsed.response;
    const { format, fields } = parsed.data;

    const requestedFields = fields
      .map((f) => String(f).trim())
      .filter((f) => f.length > 0);

    const invalidFields = requestedFields.filter(
      (f: string) => !ALLOWED_USER_FIELDS.includes(f)
    );

    if (invalidFields.length > 0) {
      const diagnostics = await getSystemDiagnostics();

      return NextResponse.json(
        {
          error: "Invalid field names in export request",
          invalidFields: invalidFields,
          allowedFields: ALLOWED_USER_FIELDS,
          debug: {
            message: "Export failed due to invalid field specification",
            requestedFields: requestedFields,
            systemDiagnostics: diagnostics,
          },
        },
        { status: 400 }
      );
    }

    const userData = await prisma.user.findUnique({
      where: { id: user.id },
      include: { address: true },
    });

    if (!userData) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const exportData: Record<string, unknown> = {};
    for (const field of requestedFields) {
      if (field === "addressId") {
        exportData[field] = userData.addressId;
      } else if (field in userData) {
        exportData[field] = userData[field as keyof typeof userData];
      }
    }

    if (format === "csv") {
      const csvData = toCSV([exportData]);
      return new NextResponse(csvData, {
        headers: {
          "Content-Type": "text/csv",
          "Content-Disposition": "attachment; filename=user-data.csv",
        },
      });
    }

    return NextResponse.json({
      data: exportData,
      format,
    });
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : String(error);

    const diagnostics = await getSystemDiagnostics();

    return NextResponse.json(
      {
        error: "Failed to export user data",
        details: errorMessage,
        debug: {
          systemDiagnostics: diagnostics,
        },
      },
      { status: 500 }
    );
  }
});
