    );
  }
});

const updateOrderStatus = async (
  request: NextRequest,
  orderId: string,
  user: JWTPayload
): Promise<NextResponse> => {
  try {
    if (user.role !== "ADMIN") {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const contentType = request.headers.get("content-type");
    const parsed = contentType?.includes("application/x-www-form-urlencoded")
      ? await parseFormData(request, updateOrderStatusBodySchema)
      : await parseBody(request, updateOrderStatusBodySchema);
    if (!parsed.success) return parsed.response;
    const status = parsed.data.status;

    const validStatuses: Array<
      "PENDING" | "PROCESSING" | "SHIPPED" | "DELIVERED" | "CANCELLED"
    > = ["PENDING", "PROCESSING", "SHIPPED", "DELIVERED", "CANCELLED"];
    if (
      !status ||
      !validStatuses.includes(
        status as
          | "PENDING"
          | "PROCESSING"
          | "SHIPPED"
          | "DELIVERED"
          | "CANCELLED"
      )
    ) {
      return NextResponse.json(
        {
          error: "Invalid status. Must be one of: " + validStatuses.join(", "),
        },
        { status: 400 }
      );
    }

    const order = await prisma.order.findUnique({
      where: { id: orderId },
    });

    if (!order) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    const updatedOrder = await prisma.order.update({
      where: { id: orderId },
      data: {
        status: status as
          | "PENDING"
          | "PROCESSING"
          | "SHIPPED"
          | "DELIVERED"
          | "CANCELLED",
      },
    });





    const response: {
      success: boolean;
      order: {
        id: string;
        status: string;
      };

    } = {
      success: true,
      order: {
        id: updatedOrder.id,
        status: updatedOrder.status,
      },
    };










    return NextResponse.json(response);
  } catch (error) {
    logger.error(
      { err: error, route: "/api/orders/[id]" },
      "Error updating order"
    );
    return NextResponse.json(
      { error: "Failed to update order" },
      { status: 500 }
    );
  }
};

export const PATCH = withAuth(async (request: NextRequest, context, user) => {
  const { id } = await context.params;
  return updateOrderStatus(request, id, user);
});

export const POST = withAuth(async (request: NextRequest, context, user) => {
  const { id } = await context.params;
  return updateOrderStatus(request, id, user);
});
