import { prisma } from "@/lib/prisma";
import { withAdminAuth } from "@/lib/server-auth";
import { writeFile, mkdir } from "fs/promises";
import { join } from "path";
import { existsSync } from "fs";
import { logger } from "@/lib/logger";

const ALLOWED_CONTENT_TYPES = [
  "image/jpeg",
  "image/png",
  "image/gif",
  "image/webp",
  "image/svg+xml",
];

const MAX_FILE_SIZE = 5 * 1024 * 1024;













export const POST = withAdminAuth(
  async (request: NextRequest, context, _user) => {
    try {
      const { id } = await context.params;

      const product = await prisma.product.findUnique({
        where: { id },
      });

      if (!product) {
        return NextResponse.json(
          { error: "Product not found" },
          { status: 404 }
        );
      }

      const formData = await request.formData();
      const file = formData.get("image") as File | null;

      if (!file) {
        return NextResponse.json(
          { error: "No image file provided" },
          { status: 400 }
        );
      }

      if (file.size > MAX_FILE_SIZE) {
        return NextResponse.json(
          { error: "File size exceeds 5MB limit" },
          { status: 400 }
        );
      }

      if (!ALLOWED_CONTENT_TYPES.includes(file.type)) {
        return NextResponse.json(
          {
            error:
              "Invalid file type. Allowed types: JPEG, PNG, GIF, WebP, SVG",
          },
          { status: 400 }
        );
      }

      const uploadsDir = join(process.cwd(), "uploads");
      if (!existsSync(uploadsDir)) {
        await mkdir(uploadsDir, { recursive: true });
      }

      const timestamp = Date.now();
      const originalName = file.name.replace(/[^a-zA-Z0-9.-]/g, "_");
      const filename = `${id}-${timestamp}-${originalName}`;

      const buffer = Buffer.from(await file.arrayBuffer());
      const filepath = join(uploadsDir, filename);
      await writeFile(filepath, buffer);

      const imageUrl = `/api/uploads/${filename}`;

      await prisma.product.update({
        where: { id },
        data: { imageUrl },
      });


















      return NextResponse.json({
        message: "Image uploaded successfully",
        imageUrl,
        productName: product.name,
      });
    } catch (error) {
      logger.error(
        { err: error, route: "/api/admin/products/[id]/image" },
        "Error uploading image"
      );
      return NextResponse.json(
        { error: "Failed to upload image" },
        { status: 500 }
      );
    }
  }
);

